-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000008_coupons_affiliates.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0008: coupons, affiliate programme, order discounts
--                              and owner-controlled site settings
--
-- Authority model (unchanged from 0004): the client may *suggest* a coupon or referral code,
-- but `place_order()` re-reads the coupon, re-validates it and recomputes every figure. A
-- tampered checkout cannot invent a discount.
-- ═════════════════════════════════════════════════════════════════════════════

-- 1. COUPONS -----------------------------------------------------------------
-- Codes are stored uppercase. There is deliberately NO public SELECT policy: customers may
-- only learn whether a code they typed is valid, via the server-side preview endpoint.

CREATE TABLE public.coupons (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code               VARCHAR(32) UNIQUE NOT NULL,
    description        TEXT,
    discount_type      TEXT NOT NULL CHECK (discount_type IN ('percent', 'fixed')),
    discount_value     NUMERIC(10, 2) NOT NULL CHECK (discount_value > 0),
    min_order_npr      NUMERIC(10, 2) NOT NULL DEFAULT 0 CHECK (min_order_npr >= 0),
    -- Caps a percentage discount so "20% off" can never exceed a sane amount.
    max_discount_npr   NUMERIC(10, 2) CHECK (max_discount_npr IS NULL OR max_discount_npr > 0),
    usage_limit        INT CHECK (usage_limit IS NULL OR usage_limit > 0),
    used_count         INT NOT NULL DEFAULT 0 CHECK (used_count >= 0),
    per_customer_limit INT NOT NULL DEFAULT 1 CHECK (per_customer_limit > 0),
    starts_at          TIMESTAMPTZ,
    ends_at            TIMESTAMPTZ,
    is_active          BOOLEAN NOT NULL DEFAULT TRUE,
    created_at         TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at         TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
    CONSTRAINT coupons_window_valid CHECK (ends_at IS NULL OR starts_at IS NULL OR ends_at > starts_at)
);

CREATE INDEX coupons_code_active_idx ON public.coupons (upper(code)) WHERE is_active;

CREATE TRIGGER coupons_touch_updated_at
    BEFORE UPDATE ON public.coupons
    FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- 2. AFFILIATES --------------------------------------------------------------
-- Anyone may apply (INSERT) as long as they insert themselves as 'pending'. Only staff can
-- read the list, approve, change rates or record payouts.

CREATE TABLE public.affiliates (
    id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    name               VARCHAR(120) NOT NULL,
    email              VARCHAR(160),
    phone              VARCHAR(20) NOT NULL,
    code               VARCHAR(32) UNIQUE NOT NULL,
    commission_rate    NUMERIC(5, 2) NOT NULL DEFAULT 5 CHECK (commission_rate >= 0 AND commission_rate <= 50),
    status             TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'active', 'suspended')),
    payout_notes       TEXT,
    total_earned_npr   NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (total_earned_npr >= 0),
    total_paid_npr     NUMERIC(12, 2) NOT NULL DEFAULT 0 CHECK (total_paid_npr >= 0),
    notes              TEXT,
    created_at         TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
    updated_at         TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE INDEX affiliates_status_idx ON public.affiliates (status);
CREATE INDEX affiliates_code_idx ON public.affiliates (upper(code));

CREATE TRIGGER affiliates_touch_updated_at
    BEFORE UPDATE ON public.affiliates
    FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- 3. ORDER FIELDS ------------------------------------------------------------

ALTER TABLE public.orders
    ADD COLUMN discount_npr   NUMERIC(10, 2) NOT NULL DEFAULT 0 CHECK (discount_npr >= 0),
    ADD COLUMN coupon_code    VARCHAR(32),
    ADD COLUMN affiliate_code VARCHAR(32),
    ADD COLUMN commission_npr NUMERIC(10, 2) NOT NULL DEFAULT 0 CHECK (commission_npr >= 0);

COMMENT ON COLUMN public.orders.discount_npr IS
    'Coupon discount actually applied, recomputed server-side in place_order().';
COMMENT ON COLUMN public.orders.commission_npr IS
    'Affiliate commission earned on this order, computed from the subtotal.';

-- 4. OWNER-CONTROLLED SITE SETTINGS -----------------------------------------

ALTER TABLE public.salon_settings
    ADD COLUMN cookie_notice_enabled  BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN cookie_notice_text     TEXT DEFAULT
        'We use cookies to keep your cart working and to understand which products people like. You can accept all, or keep only what the site needs to function.',
    ADD COLUMN app_prompt_enabled     BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN app_prompt_text        TEXT DEFAULT
        'Install the Alikati Beauty Home app for faster checkout and order updates — straight from your home screen. No app store needed.',
    -- Order in which the landing-page sections appear. The owner reorders these in /admin/settings.
    ADD COLUMN home_section_order     JSONB NOT NULL DEFAULT
        '["products", "services", "academy", "portfolio", "reviews"]'::jsonb,
    ADD COLUMN affiliate_enabled      BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN affiliate_commission_rate NUMERIC(5, 2) NOT NULL DEFAULT 5
        CHECK (affiliate_commission_rate >= 0 AND affiliate_commission_rate <= 50),
    ADD COLUMN affiliate_terms        TEXT DEFAULT
        'Share your link. When someone orders through it, you earn a commission on the product subtotal. Commissions are paid out monthly by eSewa or bank transfer once they reach रू 1,000.';

COMMENT ON COLUMN public.salon_settings.home_section_order IS
    'Landing-page section keys in display order. Unknown keys are ignored; missing keys are appended.';

-- 5. PLACE_ORDER — coupon + affiliate aware ----------------------------------
-- Rewritten from 0004. Everything else is unchanged: prices are re-read, stock is reserved
-- under a row lock, and the caller cannot influence any figure except by choosing products.
--
-- This revision returns four extra columns (discount, coupon_applied, affiliate_applied), and
-- PostgreSQL refuses to change a function's OUT-parameter row type through CREATE OR REPLACE:
--   ERROR: cannot change return type of existing function
--   HINT:  Use DROP FUNCTION place_order(jsonb) first.
-- The previous definition is therefore dropped explicitly. Nothing depends on it — the
-- application calls it through PostgREST by name — and the REVOKE below re-applies the
-- same lockdown to the new definition.
DROP FUNCTION IF EXISTS public.place_order(JSONB);

CREATE OR REPLACE FUNCTION public.place_order(payload JSONB)
RETURNS TABLE (
    order_id UUID,
    order_reference VARCHAR,
    subtotal NUMERIC,
    discount NUMERIC,
    shipping NUMERIC,
    total NUMERIC,
    coupon_applied VARCHAR,
    affiliate_applied VARCHAR
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_item            JSONB;
    v_product         public.products;
    v_qty             INT;
    v_subtotal        NUMERIC(10, 2) := 0;
    v_discount        NUMERIC(10, 2) := 0;
    v_shipping        NUMERIC(10, 2) := 0;
    v_fee             NUMERIC(10, 2);
    v_threshold       NUMERIC(10, 2);
    v_order_id        UUID := gen_random_uuid();
    v_ref             VARCHAR(20);
    v_settings        public.salon_settings;
    v_coupon          public.coupons;
    v_coupon_code     VARCHAR(32);
    v_affiliate       public.affiliates;
    v_affiliate_code  VARCHAR(32);
    v_commission      NUMERIC(10, 2) := 0;
    v_customer_id     UUID;
    v_line_count      INT := 0;
BEGIN
    IF payload->'items' IS NULL OR jsonb_array_length(payload->'items') = 0 THEN
        RAISE EXCEPTION 'EMPTY_CART';
    END IF;

    IF jsonb_array_length(payload->'items') > 25 THEN
        RAISE EXCEPTION 'TOO_MANY_LINES';
    END IF;

    SELECT * INTO v_settings FROM public.salon_settings WHERE id = 1;

    v_customer_id := NULLIF(payload->>'customer_id', '')::UUID;

    v_ref := 'ABH-ORD-' || upper(substr(replace(v_order_id::text, '-', ''), 1, 6));

    ------------------------------------------------------------------ line items
    FOR v_item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP
        v_qty := GREATEST(1, LEAST(COALESCE((v_item->>'quantity')::INT, 1), 20));
        v_line_count := v_line_count + 1;

        -- Row lock: prevents two simultaneous checkouts from overselling the same product.
        SELECT * INTO v_product FROM public.products
        WHERE id = (v_item->>'product_id')::UUID
        FOR UPDATE;

        IF NOT FOUND OR NOT v_product.is_active THEN
            RAISE EXCEPTION 'PRODUCT_UNAVAILABLE:%', COALESCE(v_item->>'product_id', 'unknown');
        END IF;

        IF v_product.stock_qty < v_qty THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK:%', v_product.name;
        END IF;

        v_subtotal := v_subtotal + (public.effective_price(v_product.price_npr, v_product.discount_price_npr) * v_qty);
    END LOOP;

    --------------------------------------------------------------------- coupon
    v_coupon_code := upper(trim(COALESCE(payload->>'coupon_code', '')));

    IF v_coupon_code <> '' THEN
        SELECT * INTO v_coupon FROM public.coupons AS c WHERE upper(c.code) = v_coupon_code;

        IF FOUND THEN
            IF NOT v_coupon.is_active THEN
                RAISE EXCEPTION 'COUPON_INACTIVE';
            END IF;
            IF v_coupon.starts_at IS NOT NULL AND now() < v_coupon.starts_at THEN
                RAISE EXCEPTION 'COUPON_NOT_STARTED';
            END IF;
            IF v_coupon.ends_at IS NOT NULL AND now() > v_coupon.ends_at THEN
                RAISE EXCEPTION 'COUPON_EXPIRED';
            END IF;
            IF v_coupon.usage_limit IS NOT NULL AND v_coupon.used_count >= v_coupon.usage_limit THEN
                RAISE EXCEPTION 'COUPON_EXHAUSTED';
            END IF;
            IF v_subtotal < v_coupon.min_order_npr THEN
                RAISE EXCEPTION 'COUPON_MIN_ORDER:%', v_coupon.min_order_npr;
            END IF;
            IF v_coupon.per_customer_limit IS NOT NULL AND v_coupon.per_customer_limit > 0 THEN
                IF EXISTS (
                    SELECT 1 FROM public.orders o
                    WHERE upper(COALESCE(o.coupon_code, '')) = v_coupon_code
                      AND (
                            (v_customer_id IS NOT NULL AND o.customer_id = v_customer_id)
                         OR (v_customer_id IS NULL AND o.customer_phone = payload->>'customer_phone')
                      )
                ) THEN
                    RAISE EXCEPTION 'COUPON_ALREADY_USED';
                END IF;
            END IF;

            IF v_coupon.discount_type = 'percent' THEN
                v_discount := round(v_subtotal * v_coupon.discount_value / 100, 2);
            ELSE
                v_discount := v_coupon.discount_value;
            END IF;

            IF v_coupon.max_discount_npr IS NOT NULL THEN
                v_discount := LEAST(v_discount, v_coupon.max_discount_npr);
            END IF;

            -- Never discount below zero, and never more than the goods are worth.
            v_discount := LEAST(GREATEST(v_discount, 0), v_subtotal);
        END IF;
        -- An unknown code is silently ignored rather than failing the whole order: the customer
        -- still gets their goods, and the response reports no coupon applied.
    END IF;

    ------------------------------------------------------------------ shipping
    v_fee := COALESCE(v_settings.shipping_fee_npr, 0);
    v_threshold := COALESCE(v_settings.free_shipping_threshold_npr, 0);
    v_shipping := CASE WHEN v_threshold > 0 AND v_subtotal >= v_threshold THEN 0 ELSE v_fee END;

    ----------------------------------------------------------------- affiliate
    v_affiliate_code := upper(trim(COALESCE(payload->>'affiliate_code', '')));

    IF v_affiliate_code <> '' THEN
        SELECT * INTO v_affiliate FROM public.affiliates AS a WHERE upper(a.code) = v_affiliate_code;

        IF FOUND AND v_affiliate.status = 'active' THEN
            v_commission := round(v_subtotal * v_affiliate.commission_rate / 100, 2);
        ELSE
            -- Unknown or inactive referral: record nothing rather than the raw code.
            v_affiliate_code := NULL;
        END IF;
    ELSE
        v_affiliate_code := NULL;
    END IF;

    ---------------------------------------------------------------- order rows
    INSERT INTO public.orders (
        id, reference, customer_id, customer_name, customer_phone, customer_email,
        delivery_address, delivery_city, delivery_landmark, notes,
        status, payment_method, payment_status,
        subtotal_npr, discount_npr, shipping_npr, total_npr,
        coupon_code, affiliate_code, commission_npr
    ) VALUES (
        v_order_id, v_ref, v_customer_id,
        payload->>'customer_name', payload->>'customer_phone', payload->>'customer_email',
        payload->>'delivery_address', payload->>'delivery_city', payload->>'delivery_landmark',
        payload->>'notes',
        'pending',
        COALESCE((payload->>'payment_method')::public.payment_method, 'cod'),
        'unpaid',
        v_subtotal, v_discount, v_shipping,
        v_subtotal - v_discount + v_shipping,
        NULLIF(v_coupon_code, ''), v_affiliate_code, v_commission
    );

    FOR v_item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP
        v_qty := GREATEST(1, LEAST(COALESCE((v_item->>'quantity')::INT, 1), 20));

        SELECT * INTO v_product FROM public.products WHERE id = (v_item->>'product_id')::UUID;

        INSERT INTO public.order_items (
            order_id, product_id, product_name, variant, unit_price_npr, quantity, line_total_npr
        ) VALUES (
            v_order_id, v_product.id, v_product.name, NULLIF(v_item->>'variant', ''),
            public.effective_price(v_product.price_npr, v_product.discount_price_npr), v_qty,
            public.effective_price(v_product.price_npr, v_product.discount_price_npr) * v_qty
        );

        UPDATE public.products
        SET stock_qty = stock_qty - v_qty
        WHERE id = v_product.id;
    END LOOP;

    IF NULLIF(v_coupon_code, '') IS NOT NULL AND v_discount > 0 THEN
        UPDATE public.coupons SET used_count = used_count + 1 WHERE upper(code) = v_coupon_code;
    END IF;

    IF v_affiliate_code IS NOT NULL AND v_commission > 0 THEN
        UPDATE public.affiliates
        SET total_earned_npr = total_earned_npr + v_commission
        WHERE upper(code) = v_affiliate_code;
    END IF;

    RETURN QUERY SELECT
        v_order_id, v_ref, v_subtotal, v_discount, v_shipping,
        v_subtotal - v_discount + v_shipping,
        NULLIF(v_coupon_code, '')::VARCHAR, v_affiliate_code::VARCHAR;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.place_order(JSONB) FROM anon, authenticated;

-- 6. COUPON PREVIEW ----------------------------------------------------------
-- Advisory only, for the checkout UI. Called by the server route with the service role; the
-- authoritative application happens inside place_order().

CREATE OR REPLACE FUNCTION public.preview_coupon(p_code TEXT, p_subtotal NUMERIC)
RETURNS TABLE (
    valid BOOLEAN,
    reason TEXT,
    code VARCHAR,
    discount_type TEXT,
    discount_value NUMERIC,
    discount_npr NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_coupon public.coupons;
    v_code   VARCHAR(32) := upper(trim(COALESCE(p_code, '')));
    v_off    NUMERIC(10, 2);
BEGIN
    IF v_code = '' THEN
        RETURN QUERY SELECT FALSE, 'Enter a code.', NULL::VARCHAR, NULL::TEXT, NULL::NUMERIC, 0::NUMERIC;
        RETURN;
    END IF;

    -- The table MUST be aliased here: `code` is also an OUT parameter of this function, and
    -- PL/pgSQL resolves an unqualified reference to the variable rather than the column,
    -- raising `column reference "code" is ambiguous` at runtime. This bug was caught by
    -- supabase/local/run-local-tests.sh — every coupon check failed with it.
    SELECT * INTO v_coupon FROM public.coupons AS c WHERE upper(c.code) = v_code;

    IF NOT FOUND THEN
        RETURN QUERY SELECT FALSE, 'That code is not recognised.', NULL::VARCHAR, NULL::TEXT, NULL::NUMERIC, 0::NUMERIC;
        RETURN;
    END IF;
    IF NOT v_coupon.is_active THEN
        RETURN QUERY SELECT FALSE, 'That offer has ended.', v_code, NULL::TEXT, NULL::NUMERIC, 0::NUMERIC;
        RETURN;
    END IF;
    IF v_coupon.starts_at IS NOT NULL AND now() < v_coupon.starts_at THEN
        RETURN QUERY SELECT FALSE, 'That offer has not started yet.', v_code, NULL::TEXT, NULL::NUMERIC, 0::NUMERIC;
        RETURN;
    END IF;
    IF v_coupon.ends_at IS NOT NULL AND now() > v_coupon.ends_at THEN
        RETURN QUERY SELECT FALSE, 'That code expired.', v_code, NULL::TEXT, NULL::NUMERIC, 0::NUMERIC;
        RETURN;
    END IF;
    IF v_coupon.usage_limit IS NOT NULL AND v_coupon.used_count >= v_coupon.usage_limit THEN
        RETURN QUERY SELECT FALSE, 'That offer has been fully claimed.', v_code, NULL::TEXT, NULL::NUMERIC, 0::NUMERIC;
        RETURN;
    END IF;
    IF p_subtotal < v_coupon.min_order_npr THEN
        RETURN QUERY SELECT FALSE,
            'Spend at least रू ' || to_char(v_coupon.min_order_npr, 'FM999,999,990') || ' to use this code.',
            v_code, v_coupon.discount_type, v_coupon.discount_value, 0::NUMERIC;
        RETURN;
    END IF;

    IF v_coupon.discount_type = 'percent' THEN
        v_off := round(p_subtotal * v_coupon.discount_value / 100, 2);
    ELSE
        v_off := v_coupon.discount_value;
    END IF;
    IF v_coupon.max_discount_npr IS NOT NULL THEN
        v_off := LEAST(v_off, v_coupon.max_discount_npr);
    END IF;
    v_off := LEAST(GREATEST(v_off, 0), p_subtotal);

    RETURN QUERY SELECT TRUE, 'Code applied.', v_code, v_coupon.discount_type, v_coupon.discount_value, v_off;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.preview_coupon(TEXT, NUMERIC) FROM anon, authenticated;

-- 7. RLS ---------------------------------------------------------------------

ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.affiliates ENABLE ROW LEVEL SECURITY;

-- Coupons: staff manage them. No public policy at all — a customer can only test a code they
-- already hold, through the server-side preview endpoint.
CREATE POLICY coupons_read_staff ON public.coupons
    FOR SELECT USING (public.is_staff());
CREATE POLICY coupons_insert_admin ON public.coupons
    FOR INSERT WITH CHECK (public.is_admin());
CREATE POLICY coupons_update_admin ON public.coupons
    FOR UPDATE USING (public.is_admin()) WITH CHECK (public.is_admin());
CREATE POLICY coupons_delete_admin ON public.coupons
    FOR DELETE USING (public.is_admin());

-- Affiliates: anyone may apply, but only as a pending applicant with no earnings.
CREATE POLICY affiliates_apply_public ON public.affiliates
    FOR INSERT WITH CHECK (
        status = 'pending'
        AND total_earned_npr = 0
        AND total_paid_npr = 0
    );
CREATE POLICY affiliates_read_staff ON public.affiliates
    FOR SELECT USING (public.is_staff());
CREATE POLICY affiliates_update_staff ON public.affiliates
    FOR UPDATE USING (public.is_staff()) WITH CHECK (public.is_staff());
CREATE POLICY affiliates_delete_admin ON public.affiliates
    FOR DELETE USING (public.is_admin());

-- 8. VERIFY ------------------------------------------------------------------
SELECT 'coupons' AS object, count(*) FROM public.coupons
UNION ALL
SELECT 'affiliates', count(*) FROM public.affiliates;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000009_security_hardening.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0009: security hardening for the privileged RPCs
--
-- WHY THIS EXISTS
-- ---------------
-- PostgreSQL grants EXECUTE on every new function to PUBLIC by default. That means the
-- earlier statements in 0004/0008:
--
--     REVOKE EXECUTE ON FUNCTION public.place_order(JSONB) FROM anon, authenticated;
--
-- did nothing useful: `anon` and `authenticated` still inherit EXECUTE through PUBLIC, so the
-- functions remained callable straight from the browser via PostgREST, e.g.
--
--     POST /rest/v1/rpc/place_order     (with the public anon key)
--     POST /rest/v1/rpc/preview_coupon  (coupon-code enumeration)
--     POST /rest/v1/rpc/cancel_order    (cancel any order and restore its stock)
--     POST /rest/v1/rpc/shop_kpis       (read the shop's revenue figures)
--
-- This migration revokes from PUBLIC and re-grants narrowly, then adds an internal staff check
-- to the two functions that staff call from the browser. Defence in depth: even if a grant is
-- widened by mistake later, SECURITY DEFINER functions still refuse a non-staff caller.
--
-- Verified by `supabase/local/run-local-tests.sh`, which asserts the exact privilege matrix.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── 1. Close the PUBLIC grants ────────────────────────────────────────────────
-- Server-only RPCs: executed by the service-role key from the Next.js route handlers.
REVOKE EXECUTE ON FUNCTION public.place_order(JSONB) FROM PUBLIC, anon, authenticated;
REVOKE EXECUTE ON FUNCTION public.preview_coupon(TEXT, NUMERIC) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.place_order(JSONB) TO service_role;
GRANT EXECUTE ON FUNCTION public.preview_coupon(TEXT, NUMERIC) TO service_role;

-- Staff-facing RPCs, called from the admin console in the browser (a signed-in staff JWT).
REVOKE EXECUTE ON FUNCTION public.cancel_order(UUID) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.shop_kpis(DATE) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.attach_order_to_customer(TEXT, TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cancel_order(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.shop_kpis(DATE) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.attach_order_to_customer(TEXT, TEXT) TO authenticated, service_role;

-- ── 2. cancel_order(): staff only ─────────────────────────────────────────────
-- SECURITY DEFINER bypasses RLS, so a customer holding a valid session could otherwise cancel
-- somebody else's order and silently put its stock back on the shelf.
CREATE OR REPLACE FUNCTION public.cancel_order(p_order_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_current public.order_status;
BEGIN
    IF NOT public.is_staff() THEN
        RAISE EXCEPTION 'NOT_AUTHORISED_STAFF_ONLY';
    END IF;

    SELECT status INTO v_current FROM public.orders WHERE id = p_order_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'ORDER_NOT_FOUND';
    END IF;
    IF v_current = 'cancelled' THEN
        RETURN;                                 -- already cancelled; nothing to restore
    END IF;
    IF v_current = 'delivered' THEN
        RAISE EXCEPTION 'CANNOT_CANCEL_DELIVERED';
    END IF;

    UPDATE public.products p
    SET stock_qty = p.stock_qty + oi.quantity
    FROM public.order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.product_id = p.id;

    UPDATE public.orders
    SET status = 'cancelled'
    WHERE id = p_order_id;
END;
$$;

-- ── 3. shop_kpis(): staff only ────────────────────────────────────────────────
-- Returns revenue, so it must not be readable by a customer who happens to hold a session.
CREATE OR REPLACE FUNCTION public.shop_kpis(
    p_date DATE DEFAULT (timezone('Asia/Kathmandu', now()))::date
)
RETURNS TABLE (
    orders_today     BIGINT,
    revenue_today    NUMERIC,
    orders_pending   BIGINT,
    orders_shipped   BIGINT,
    low_stock_count  BIGINT,
    units_sold_month BIGINT
)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    IF NOT public.is_staff() THEN
        RAISE EXCEPTION 'NOT_AUTHORISED_STAFF_ONLY';
    END IF;

    RETURN QUERY
    SELECT
        (SELECT count(*) FROM public.orders WHERE created_at::date = p_date AND status <> 'cancelled'),
        (SELECT COALESCE(SUM(total_npr), 0) FROM public.orders WHERE created_at::date = p_date AND status <> 'cancelled'),
        (SELECT count(*) FROM public.orders WHERE status = 'pending'),
        (SELECT count(*) FROM public.orders WHERE status IN ('packed', 'shipped')),
        (SELECT count(*) FROM public.products WHERE is_active AND stock_qty <= low_stock_threshold),
        (SELECT COALESCE(SUM(oi.quantity), 0)
           FROM public.order_items oi
           JOIN public.orders o ON o.id = oi.order_id
          WHERE o.status <> 'cancelled'
            AND o.created_at >= date_trunc('month', timezone('Asia/Kathmandu', now())));
END;
$$;

-- NOTE: because this file re-created the two functions above, PostgreSQL reset their grants to
-- the default (EXECUTE to PUBLIC). The revokes must therefore be repeated after the bodies.
REVOKE EXECUTE ON FUNCTION public.cancel_order(UUID) FROM PUBLIC, anon;
REVOKE EXECUTE ON FUNCTION public.shop_kpis(DATE) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.cancel_order(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.shop_kpis(DATE) TO authenticated, service_role;

-- ── 4. Report the resulting privilege matrix ─────────────────────────────────
DO $$
DECLARE
    r RECORD;
    exposed TEXT[] := ARRAY[]::TEXT[];
BEGIN
    FOR r IN
        SELECT p.proname,
               has_function_privilege('anon', p.oid, 'EXECUTE')          AS anon_can,
               has_function_privilege('authenticated', p.oid, 'EXECUTE') AS user_can
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = 'public'
          AND p.proname IN ('place_order', 'preview_coupon', 'cancel_order', 'shop_kpis')
    LOOP
        RAISE NOTICE 'RPC % — anon: %, authenticated: %', r.proname, r.anon_can, r.user_can;
        IF r.anon_can THEN
            exposed := exposed || r.proname;
        END IF;
    END LOOP;

    IF array_length(exposed, 1) > 0 THEN
        RAISE EXCEPTION 'these RPCs are still callable with the public anon key: %', exposed;
    END IF;
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000010_auth_role_separation.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0010: CRITICAL — separate customer signups from staff access
--
-- THE BUG THIS FIXES
-- ------------------
-- `handle_new_staff_user()` (0001) fires on EVERY row inserted into `auth.users` and
-- unconditionally created a `profiles` row with role `staff`:
--
--     CASE WHEN NEW.raw_user_meta_data->>'role' = 'admin' THEN 'admin' ELSE 'staff' END
--
-- Customer signups also insert into `auth.users`, so every person who registered at
-- /account/signup was given role `staff`. `is_staff()` — which every RLS policy for orders,
-- appointments, customers, coupons, products and services keys off — then returned TRUE for
-- them. Verified against a real database before this fix:
--
--     customer signup → role "staff"
--     → SELECT count(*) FROM orders      → 2   (names, phones, delivery addresses)
--     → SELECT count(*) FROM customers   → 1
--     → UPDATE products SET price_npr=1  → SUCCEEDED
--
-- Anyone could self-register and take over the storefront. No data was at risk in practice
-- because the project had not been deployed yet — but `supabase db push` would have shipped
-- this. Found by supabase/local/run-local-tests.sh.
--
-- THE FIX
-- -------
-- A profile is now provisioned ONLY when the signup explicitly declares a staff role in its
-- user metadata (`role: 'admin' | 'staff'`). `scripts/create-admin.mjs` already sets
-- `user_metadata: { full_name, role: 'admin' }`, so admin creation is unaffected.
--
-- ⚠ IMPORTANT FOR STAFF INVITATIONS: inviting a staff member from the Supabase dashboard
--   without adding a `role` key to their user metadata will NOT create a profile, and they
--   will be unable to sign in to the console. Either use scripts/create-admin.mjs, or add
--     { "role": "staff" }
--   to the user's metadata in the dashboard and re-save.
-- ═════════════════════════════════════════════════════════════════════════════

-- ── 1. Staff profiles require an explicit staff invitation ────────────────────
CREATE OR REPLACE FUNCTION public.handle_new_staff_user()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    v_role TEXT := COALESCE(NEW.raw_user_meta_data->>'role', '');
BEGIN
    -- No `role` claim means this is a customer signup, not staff. Do nothing at all.
    IF v_role NOT IN ('admin', 'staff') THEN
        RETURN NEW;
    END IF;

    INSERT INTO public.profiles (id, email, full_name, role)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NULLIF(NEW.raw_user_meta_data->>'full_name', ''), 'Staff Member'),
        CASE WHEN v_role = 'admin' THEN 'admin' ELSE 'staff' END
    )
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$$;

-- ── 2. Staff are not customers ────────────────────────────────────────────────
-- Symmetry: a user who declared a staff role should not also land in the customer list.
CREATE OR REPLACE FUNCTION public.handle_new_customer()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    -- Customer accounts are email-based; ignore anything else (e.g. phone-only users).
    IF NEW.email IS NULL THEN
        RETURN NEW;
    END IF;

    -- Staff invitations are not customers.
    IF COALESCE(NEW.raw_user_meta_data->>'role', '') IN ('admin', 'staff') THEN
        RETURN NEW;
    END IF;

    INSERT INTO public.customers (id, email, full_name, phone, marketing_opt_in)
    VALUES (
        NEW.id,
        NEW.email,
        COALESCE(NULLIF(NEW.raw_user_meta_data->>'full_name', ''), 'Customer'),
        NULLIF(NEW.raw_user_meta_data->>'phone', ''),
        COALESCE((NEW.raw_user_meta_data->>'marketing_opt_in')::boolean, FALSE)
    )
    ON CONFLICT (id) DO NOTHING;

    RETURN NEW;
END;
$$;

-- ── 3. Remove profiles wrongly created by the old trigger ─────────────────────
-- Scoped deliberately narrowly: only rows that are BOTH a customer and a non-invited
-- `staff` profile are removed. Someone genuinely invited as staff is left untouched, and an
-- admin is never touched.
DELETE FROM public.profiles p
USING public.customers c
WHERE p.id = c.id
  AND p.role = 'staff'
  AND COALESCE(
        (SELECT u.raw_user_meta_data->>'role' FROM auth.users u WHERE u.id = p.id),
        ''
      ) NOT IN ('admin', 'staff');

-- ── 4. Prove it ───────────────────────────────────────────────────────────────
DO $$
DECLARE
    v_customer UUID := gen_random_uuid();
    v_staff    UUID := gen_random_uuid();
BEGIN
    -- A public customer signup: no role claim.
    INSERT INTO auth.users (id, email, raw_user_meta_data)
    VALUES (v_customer, 'role-separation-customer@example.com', '{"full_name":"Real Customer"}'::jsonb);

    IF EXISTS (SELECT 1 FROM public.profiles WHERE id = v_customer) THEN
        RAISE EXCEPTION 'SECURITY: a customer signup was given a staff profile';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.customers WHERE id = v_customer) THEN
        RAISE EXCEPTION 'a customer signup did not get a customer row';
    END IF;
    RAISE NOTICE 'L1  customer signup → customer row only, no staff profile';

    -- A staff invitation: explicit role claim.
    INSERT INTO auth.users (id, email, raw_user_meta_data)
    VALUES (v_staff, 'role-separation-staff@example.com',
            '{"full_name":"Real Staff","role":"staff"}'::jsonb);

    IF NOT EXISTS (SELECT 1 FROM public.profiles WHERE id = v_staff AND role = 'staff') THEN
        RAISE EXCEPTION 'a staff invitation did not create a staff profile';
    END IF;
    IF EXISTS (SELECT 1 FROM public.customers WHERE id = v_staff) THEN
        RAISE EXCEPTION 'a staff member was also created as a customer';
    END IF;
    RAISE NOTICE 'L2  staff invitation → staff profile only, not a customer';

    -- And confirm the escalation is closed: the customer cannot read the order book.
    PERFORM set_config('request.jwt.claim.sub', v_customer::text, true);
    IF public.is_staff() THEN
        RAISE EXCEPTION 'SECURITY: is_staff() is still true for a customer';
    END IF;
    RAISE NOTICE 'L3  is_staff() is false for a customer account';

    -- Tidy up the probe rows so the database is left as we found it.
    DELETE FROM public.customers WHERE id = v_customer;
    DELETE FROM public.profiles WHERE id IN (v_customer, v_staff);
    DELETE FROM auth.users WHERE id IN (v_customer, v_staff);
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000011_payments_staff_nepali_dates.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0011
--   §1 staff account management (activate/deactivate without deleting the auth user)
--   §2 FIX: is_staff() never checked the role
--   §3 payment QR + proof-of-payment uploads
--   §4 Nepali (Bikram Sambat) date display + coupon duration defaults
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. Staff account management ─────────────────────────────────────────────
-- Deleting an auth user would orphan their order/appointment history, so staff are
-- deactivated instead. `is_active` is read by the helpers above.
ALTER TABLE public.profiles
    ADD COLUMN IF NOT EXISTS is_active     BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN IF NOT EXISTS phone         VARCHAR(20),
    ADD COLUMN IF NOT EXISTS last_login_at TIMESTAMPTZ;

CREATE INDEX IF NOT EXISTS idx_profiles_active ON public.profiles (is_active) WHERE is_active;

-- Admins may edit other people's profiles (role changes, deactivation, correction of names).
DROP POLICY IF EXISTS "profiles_admin_update" ON public.profiles;
CREATE POLICY "profiles_admin_update" ON public.profiles
    FOR UPDATE TO authenticated
    USING (public.is_admin())
    WITH CHECK (public.is_admin());

-- Staff may see the team list (needed by the admin console's users screen).
DROP POLICY IF EXISTS "profiles_staff_select" ON public.profiles;
CREATE POLICY "profiles_staff_select" ON public.profiles
    FOR SELECT TO authenticated
    USING (public.is_staff() OR id = auth.uid());

-- ── §2. is_staff() / is_admin() were checking only that a row EXISTED ─────────
-- As shipped, is_staff() was:
--     SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = auth.uid());
-- It never inspected `role` or `is_active`, so every RLS policy in the database —
-- orders, customers, coupons, appointments, storage — treated ANY profile row as staff.
-- Today only invited staff hold a profile (migration 0010 stopped customers getting one),
-- so this is a latent hole rather than an open door: the moment a profile row is created for
-- any other purpose, that account inherits full staff reach. Both helpers now verify the
-- role, and honour `is_active` so deactivating a person revokes access immediately.
CREATE OR REPLACE FUNCTION public.is_staff()
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid()
          AND role IN ('admin', 'staff')
          AND COALESCE(is_active, TRUE)
    );
$$;

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
    SELECT EXISTS (
        SELECT 1 FROM public.profiles
        WHERE id = auth.uid()
          AND role = 'admin'
          AND COALESCE(is_active, TRUE)
    );
$$;

-- ── §3. Payment proof and QR payment settings ────────────────────────────────
-- Customers pay by eSewa / Khalti / bank transfer and upload the statement screenshot;
-- staff review it against the order. `payment_reference` stores the transaction id the
-- customer types in.
ALTER TABLE public.orders
    ADD COLUMN IF NOT EXISTS payment_proof_url  TEXT,
    ADD COLUMN IF NOT EXISTS payment_reference  VARCHAR(80);

-- ── §4. Settings for the payment screen, Nepali dates and coupon defaults ────
ALTER TABLE public.salon_settings
    ADD COLUMN IF NOT EXISTS payment_qr_enabled     BOOLEAN NOT NULL DEFAULT TRUE,
    -- What the generated QR encodes, e.g. "esewa:9869512756" or a bank/payment URI.
    ADD COLUMN IF NOT EXISTS payment_qr_content     TEXT DEFAULT 'esewa:9869512756',
    -- If the owner uploads their own QR (from the eSewa/Khalti app), it wins over the generated one.
    ADD COLUMN IF NOT EXISTS payment_qr_image_url   TEXT,
    ADD COLUMN IF NOT EXISTS payment_note           TEXT
        DEFAULT 'Scan the QR to pay, then upload your payment screenshot below. We confirm on WhatsApp.',
    -- Default validity applied to a new coupon (days), used by the admin duration presets.
    ADD COLUMN IF NOT EXISTS coupon_default_days    INT NOT NULL DEFAULT 7,
    -- Show Bikram Sambat dates alongside AD dates across the site and admin.
    ADD COLUMN IF NOT EXISTS nepali_dates           BOOLEAN NOT NULL DEFAULT TRUE;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.salon_settings
        WHERE coupon_default_days IS NULL OR coupon_default_days < 1 OR coupon_default_days > 365
    ) THEN
        UPDATE public.salon_settings SET coupon_default_days = 7 WHERE coupon_default_days IS NULL;
        RAISE NOTICE 'coupon_default_days reset to 7 for out-of-range values';
    END IF;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'coupon_default_days check skipped: %', SQLERRM;
END $$;

-- ── §5. Private bucket for payment statements ────────────────────────────────
-- Deliberately NOT public: these are customers' payment screenshots, which can expose
-- account balances and names. Staff read them through short-lived signed URLs.
--
-- Anyone may upload (checkout happens before sign-in, and a guest must still be able to
-- prove payment), but nobody anonymous can read the bucket back. Uploads are capped at
-- 5 MB and restricted to images/PDF.
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES (
    'payment-proofs', 'payment-proofs', FALSE, 5242880,
    ARRAY['image/png','image/jpeg','image/webp','image/heic','application/pdf']
)
ON CONFLICT (id) DO UPDATE
    SET public = FALSE,
        file_size_limit = 5242880,
        allowed_mime_types = ARRAY['image/png','image/jpeg','image/webp','image/heic','application/pdf'];

DROP POLICY IF EXISTS "payment_proofs_anyone_upload" ON storage.objects;
CREATE POLICY "payment_proofs_anyone_upload" ON storage.objects
    FOR INSERT TO anon, authenticated
    WITH CHECK (bucket_id = 'payment-proofs');

DROP POLICY IF EXISTS "payment_proofs_staff_read" ON storage.objects;
CREATE POLICY "payment_proofs_staff_read" ON storage.objects
    FOR SELECT TO authenticated
    USING (bucket_id = 'payment-proofs' AND public.is_staff());

DROP POLICY IF EXISTS "payment_proofs_admin_delete" ON storage.objects;
CREATE POLICY "payment_proofs_admin_delete" ON storage.objects
    FOR DELETE TO authenticated
    USING (bucket_id = 'payment-proofs' AND public.is_admin());

-- ── §6. Verification ─────────────────────────────────────────────────────────
DO $$
DECLARE
    v_staff_role TEXT;
    v_admin_role TEXT;
BEGIN
    -- The helpers must now consult the role column, not merely the row's existence.
    SELECT pg_get_functiondef('public.is_staff()'::regprocedure) INTO v_staff_role;
    IF position('role IN' IN v_staff_role) = 0 THEN
        RAISE EXCEPTION 'is_staff() still does not check the role';
    END IF;
    IF position('is_active' IN v_staff_role) = 0 THEN
        RAISE EXCEPTION 'is_staff() ignores is_active — deactivation would not revoke access';
    END IF;

    SELECT pg_get_functiondef('public.is_admin()'::regprocedure) INTO v_admin_role;
    IF position('role = ''admin''' IN v_admin_role) = 0 THEN
        RAISE EXCEPTION 'is_admin() does not check for the admin role';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'payment-proofs' AND NOT public) THEN
        RAISE EXCEPTION 'payment-proofs bucket missing or public';
    END IF;

    RAISE NOTICE '0011 applied: role-aware staff checks, payment proofs, Nepali date settings';
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000012_place_order_customer_guard.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0012: a stale customer id must not fail a sale
--
-- THE BUG
--   The owner was signed in as an ADMIN account and clicked "Place order". The checkout sent
--   `customer_id`, but staff accounts have no row in `customers` (migration 0010 deliberately
--   creates one only for non-staff signups), so `orders.customer_id` violated its foreign key
--   and place_order() raised. The API turned that into a 500 and the customer saw the generic
--   "We could not place your order. Please call us on WhatsApp." Five such failures are in the
--   server log. Any signed-in staff account was unable to buy anything.
--
-- THE FIX (two layers)
--   1. `app/api/orders/route.ts` now creates the missing `customers` row for the verified
--      signed-in user before placing, so the order links to their account as intended.
--   2. This migration makes the function itself resilient: an id that does not exist is dropped
--      to NULL, turning a fatal error into a normal guest order.
--
-- The body below is the live definition with the guard inserted, so it cannot drift from what
-- is deployed.
-- ═════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.place_order(payload jsonb)
 RETURNS TABLE(order_id uuid, order_reference character varying, subtotal numeric, discount numeric, shipping numeric, total numeric, coupon_applied character varying, affiliate_applied character varying)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item            JSONB;
    v_product         public.products;
    v_qty             INT;
    v_subtotal        NUMERIC(10, 2) := 0;
    v_discount        NUMERIC(10, 2) := 0;
    v_shipping        NUMERIC(10, 2) := 0;
    v_fee             NUMERIC(10, 2);
    v_threshold       NUMERIC(10, 2);
    v_order_id        UUID := gen_random_uuid();
    v_ref             VARCHAR(20);
    v_settings        public.salon_settings;
    v_coupon          public.coupons;
    v_coupon_code     VARCHAR(32);
    v_affiliate       public.affiliates;
    v_affiliate_code  VARCHAR(32);
    v_commission      NUMERIC(10, 2) := 0;
    v_customer_id     UUID;
    v_line_count      INT := 0;
BEGIN
    IF payload->'items' IS NULL OR jsonb_array_length(payload->'items') = 0 THEN
        RAISE EXCEPTION 'EMPTY_CART';
    END IF;

    IF jsonb_array_length(payload->'items') > 25 THEN
        RAISE EXCEPTION 'TOO_MANY_LINES';
    END IF;

    SELECT * INTO v_settings FROM public.salon_settings WHERE id = 1;

    v_customer_id := NULLIF(payload->>'customer_id', '')::UUID;

    -- A stale or unknown customer id must never fail a sale. orders.customer_id references
    -- customers(id), and a signed-in STAFF account has no customer row (migration 0010 only
    -- creates one for non-staff signups) — so checkout 500'd for the shop owner's own account
    -- with "violates foreign key constraint orders_customer_id_fkey". Degrade to a guest order
    -- instead: the sale still completes, and the API links the account properly beforehand.
    IF v_customer_id IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM public.customers WHERE id = v_customer_id) THEN
        v_customer_id := NULL;
    END IF;

    v_ref := 'ABH-ORD-' || upper(substr(replace(v_order_id::text, '-', ''), 1, 6));

    ------------------------------------------------------------------ line items
    FOR v_item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP
        v_qty := GREATEST(1, LEAST(COALESCE((v_item->>'quantity')::INT, 1), 20));
        v_line_count := v_line_count + 1;

        -- Row lock: prevents two simultaneous checkouts from overselling the same product.
        SELECT * INTO v_product FROM public.products
        WHERE id = (v_item->>'product_id')::UUID
        FOR UPDATE;

        IF NOT FOUND OR NOT v_product.is_active THEN
            RAISE EXCEPTION 'PRODUCT_UNAVAILABLE:%', COALESCE(v_item->>'product_id', 'unknown');
        END IF;

        IF v_product.stock_qty < v_qty THEN
            RAISE EXCEPTION 'INSUFFICIENT_STOCK:%', v_product.name;
        END IF;

        v_subtotal := v_subtotal + (public.effective_price(v_product.price_npr, v_product.discount_price_npr) * v_qty);
    END LOOP;

    --------------------------------------------------------------------- coupon
    v_coupon_code := upper(trim(COALESCE(payload->>'coupon_code', '')));

    IF v_coupon_code <> '' THEN
        SELECT * INTO v_coupon FROM public.coupons AS c WHERE upper(c.code) = v_coupon_code;

        IF FOUND THEN
            IF NOT v_coupon.is_active THEN
                RAISE EXCEPTION 'COUPON_INACTIVE';
            END IF;
            IF v_coupon.starts_at IS NOT NULL AND now() < v_coupon.starts_at THEN
                RAISE EXCEPTION 'COUPON_NOT_STARTED';
            END IF;
            IF v_coupon.ends_at IS NOT NULL AND now() > v_coupon.ends_at THEN
                RAISE EXCEPTION 'COUPON_EXPIRED';
            END IF;
            IF v_coupon.usage_limit IS NOT NULL AND v_coupon.used_count >= v_coupon.usage_limit THEN
                RAISE EXCEPTION 'COUPON_EXHAUSTED';
            END IF;
            IF v_subtotal < v_coupon.min_order_npr THEN
                RAISE EXCEPTION 'COUPON_MIN_ORDER:%', v_coupon.min_order_npr;
            END IF;
            IF v_coupon.per_customer_limit IS NOT NULL AND v_coupon.per_customer_limit > 0 THEN
                IF EXISTS (
                    SELECT 1 FROM public.orders o
                    WHERE upper(COALESCE(o.coupon_code, '')) = v_coupon_code
                      AND (
                            (v_customer_id IS NOT NULL AND o.customer_id = v_customer_id)
                         OR (v_customer_id IS NULL AND o.customer_phone = payload->>'customer_phone')
                      )
                ) THEN
                    RAISE EXCEPTION 'COUPON_ALREADY_USED';
                END IF;
            END IF;

            IF v_coupon.discount_type = 'percent' THEN
                v_discount := round(v_subtotal * v_coupon.discount_value / 100, 2);
            ELSE
                v_discount := v_coupon.discount_value;
            END IF;

            IF v_coupon.max_discount_npr IS NOT NULL THEN
                v_discount := LEAST(v_discount, v_coupon.max_discount_npr);
            END IF;

            -- Never discount below zero, and never more than the goods are worth.
            v_discount := LEAST(GREATEST(v_discount, 0), v_subtotal);
        END IF;
        -- An unknown code is silently ignored rather than failing the whole order: the customer
        -- still gets their goods, and the response reports no coupon applied.
    END IF;

    ------------------------------------------------------------------ shipping
    v_fee := COALESCE(v_settings.shipping_fee_npr, 0);
    v_threshold := COALESCE(v_settings.free_shipping_threshold_npr, 0);
    v_shipping := CASE WHEN v_threshold > 0 AND v_subtotal >= v_threshold THEN 0 ELSE v_fee END;

    ----------------------------------------------------------------- affiliate
    v_affiliate_code := upper(trim(COALESCE(payload->>'affiliate_code', '')));

    IF v_affiliate_code <> '' THEN
        SELECT * INTO v_affiliate FROM public.affiliates AS a WHERE upper(a.code) = v_affiliate_code;

        IF FOUND AND v_affiliate.status = 'active' THEN
            v_commission := round(v_subtotal * v_affiliate.commission_rate / 100, 2);
        ELSE
            -- Unknown or inactive referral: record nothing rather than the raw code.
            v_affiliate_code := NULL;
        END IF;
    ELSE
        v_affiliate_code := NULL;
    END IF;

    ---------------------------------------------------------------- order rows
    INSERT INTO public.orders (
        id, reference, customer_id, customer_name, customer_phone, customer_email,
        delivery_address, delivery_city, delivery_landmark, notes,
        status, payment_method, payment_status,
        subtotal_npr, discount_npr, shipping_npr, total_npr,
        coupon_code, affiliate_code, commission_npr
    ) VALUES (
        v_order_id, v_ref, v_customer_id,
        payload->>'customer_name', payload->>'customer_phone', payload->>'customer_email',
        payload->>'delivery_address', payload->>'delivery_city', payload->>'delivery_landmark',
        payload->>'notes',
        'pending',
        COALESCE((payload->>'payment_method')::public.payment_method, 'cod'),
        'unpaid',
        v_subtotal, v_discount, v_shipping,
        v_subtotal - v_discount + v_shipping,
        NULLIF(v_coupon_code, ''), v_affiliate_code, v_commission
    );

    FOR v_item IN SELECT * FROM jsonb_array_elements(payload->'items') LOOP
        v_qty := GREATEST(1, LEAST(COALESCE((v_item->>'quantity')::INT, 1), 20));

        SELECT * INTO v_product FROM public.products WHERE id = (v_item->>'product_id')::UUID;

        INSERT INTO public.order_items (
            order_id, product_id, product_name, variant, unit_price_npr, quantity, line_total_npr
        ) VALUES (
            v_order_id, v_product.id, v_product.name, NULLIF(v_item->>'variant', ''),
            public.effective_price(v_product.price_npr, v_product.discount_price_npr), v_qty,
            public.effective_price(v_product.price_npr, v_product.discount_price_npr) * v_qty
        );

        UPDATE public.products
        SET stock_qty = stock_qty - v_qty
        WHERE id = v_product.id;
    END LOOP;

    IF NULLIF(v_coupon_code, '') IS NOT NULL AND v_discount > 0 THEN
        UPDATE public.coupons SET used_count = used_count + 1 WHERE upper(code) = v_coupon_code;
    END IF;

    IF v_affiliate_code IS NOT NULL AND v_commission > 0 THEN
        UPDATE public.affiliates
        SET total_earned_npr = total_earned_npr + v_commission
        WHERE upper(code) = v_affiliate_code;
    END IF;

    RETURN QUERY SELECT
        v_order_id, v_ref, v_subtotal, v_discount, v_shipping,
        v_subtotal - v_discount + v_shipping,
        NULLIF(v_coupon_code, '')::VARCHAR, v_affiliate_code::VARCHAR;
END;
$function$

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000013_hero_and_amount_qr.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0013
--   • editable landing-page hero (image + copy) controlled from the admin console
--   • the payment QR can now carry the order amount
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. Landing page hero, editable from admin ───────────────────────────────
-- The hero previously used a bundled placeholder illustration. The owner can now upload the
-- real salon photograph and adjust the wording without a developer.
ALTER TABLE public.salon_settings
    ADD COLUMN IF NOT EXISTS hero_image_url    TEXT,
    ADD COLUMN IF NOT EXISTS hero_heading      TEXT,
    ADD COLUMN IF NOT EXISTS hero_subheading   TEXT,
    -- Smaller image shown beside the hero on desktop; optional.
    ADD COLUMN IF NOT EXISTS hero_badge_text   TEXT;

UPDATE public.salon_settings
SET hero_heading = COALESCE(
        hero_heading,
        'Salon, bridal studio and shop in Attariya Chowk'
    ),
    hero_subheading = COALESCE(
        hero_subheading,
        'Book hair, skin, bridal and nail services, or order the products our stylists use — delivered across Kailali.'
    )
WHERE id = 1;

-- ── §2. Amount-aware payment QR ──────────────────────────────────────────────
-- `payment_qr_content` may contain the literal token `{amount}`, which the checkout replaces
-- with the live order total before drawing the QR. e.g.
--     esewa:9869512756?amount={amount}   →   esewa:9869512756?amount=1800
--
-- Two honest caveats, also surfaced in the admin hint:
--   • Whether the customer's wallet pre-fills that amount depends on the provider's QR format.
--     A genuinely provider-validated dynamic QR (Fonepay/eSewa merchant dynamic QR) needs
--     merchant API credentials, which is a separate integration.
--   • Because of that, the checkout ALWAYS prints the amount next to the code as well, so the
--     customer can never be unsure what to pay.
UPDATE public.salon_settings
SET payment_qr_content = 'esewa:9869512756?amount={amount}'
WHERE id = 1
  AND (payment_qr_content IS NULL OR position('{amount}' IN payment_qr_content) = 0);

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'public' AND table_name = 'salon_settings'
          AND column_name = 'hero_image_url'
    ) THEN
        RAISE EXCEPTION '0013 failed: hero_image_url was not added';
    END IF;
    RAISE NOTICE '0013 applied: editable hero + amount-aware payment QR';
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000014_hero_slides.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0014: hero slideshow
--
-- The landing hero was a single image (`salon_settings.hero_image_url`, migration 0013). The
-- owner wants several photographs rotating. Those live here rather than in a JSON blob so they
-- can be ordered, disabled and captioned individually — and so the public page can fetch just
-- the active ones.
--
-- `hero_image_url` is kept as a fallback: with no slides, the hero still shows it, and with
-- neither it shows the bundled placeholder.
-- ═════════════════════════════════════════════════════════════════════════════

CREATE TABLE IF NOT EXISTS public.hero_slides (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    image_url     TEXT NOT NULL,
    /** Read aloud by screen readers — describe the photo, not the file name. */
    alt_text      VARCHAR(180),
    /** Optional per-slide override of the hero heading. */
    heading       VARCHAR(120),
    subheading    VARCHAR(200),
    display_order INT NOT NULL DEFAULT 0,
    is_active     BOOLEAN NOT NULL DEFAULT TRUE,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now())
);

-- The storefront only ever asks for active slides in display order.
CREATE INDEX IF NOT EXISTS idx_hero_slides_active_order
    ON public.hero_slides (display_order)
    WHERE is_active;

DROP TRIGGER IF EXISTS trg_hero_slides_updated ON public.hero_slides;
CREATE TRIGGER trg_hero_slides_updated
    BEFORE UPDATE ON public.hero_slides
    FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- ── Access ───────────────────────────────────────────────────────────────────
ALTER TABLE public.hero_slides ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "hero_slides_public_read" ON public.hero_slides;
CREATE POLICY "hero_slides_public_read" ON public.hero_slides
    FOR SELECT TO anon, authenticated
    USING (is_active OR public.is_staff());

DROP POLICY IF EXISTS "hero_slides_staff_write" ON public.hero_slides;
CREATE POLICY "hero_slides_staff_write" ON public.hero_slides
    FOR ALL TO authenticated
    USING (public.is_staff())
    WITH CHECK (public.is_staff());

-- ── Preserve whatever hero image is already configured ───────────────────────
-- Seeds a first slide from the old single-image field so the slideshow is never empty for an
-- owner who had already uploaded a photograph. Skipped if slides already exist.
INSERT INTO public.hero_slides (image_url, alt_text, display_order, is_active)
SELECT
    s.hero_image_url,
    'Alikati Beauty Home',
    0,
    TRUE
FROM public.salon_settings s
WHERE s.id = 1
  AND s.hero_image_url IS NOT NULL
  AND btrim(s.hero_image_url) <> ''
  AND NOT EXISTS (SELECT 1 FROM public.hero_slides);

DO $$
DECLARE
    v_slides INT;
    v_policies INT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = 'hero_slides' AND relrowsecurity) THEN
        RAISE EXCEPTION '0014 failed: hero_slides does not have RLS enabled';
    END IF;

    SELECT count(*) INTO v_policies FROM pg_policies WHERE tablename = 'hero_slides';
    IF v_policies < 2 THEN
        RAISE EXCEPTION '0014 failed: expected public-read and staff-write policies, found %', v_policies;
    END IF;

    SELECT count(*) INTO v_slides FROM public.hero_slides;
    RAISE NOTICE '0014 applied: hero_slides ready (% slide(s) seeded)', v_slides;
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260928000015_promo_and_ratings.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0015
--   • owner-controlled promotional band for the landing page
--   • optional product ratings, so the new storefront card design can show stars
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. Promotional band ─────────────────────────────────────────────────────
-- The reference storefront has a "Limited Time Offer — Up to 30% OFF" strip between the
-- category grid and the best sellers. Everything about it is the owner's copy: this platform
-- must never invent a discount claim on the shop's behalf.
ALTER TABLE public.salon_settings
    ADD COLUMN IF NOT EXISTS promo_enabled      BOOLEAN NOT NULL DEFAULT TRUE,
    ADD COLUMN IF NOT EXISTS promo_eyebrow      TEXT DEFAULT 'Limited time offer',
    ADD COLUMN IF NOT EXISTS promo_headline     TEXT DEFAULT 'Festival offers are live',
    ADD COLUMN IF NOT EXISTS promo_subheadline  TEXT DEFAULT 'See everything currently reduced across the shop.',
    ADD COLUMN IF NOT EXISTS promo_cta_label    TEXT DEFAULT 'Shop the offers',
    ADD COLUMN IF NOT EXISTS promo_href         TEXT DEFAULT '/shop';

-- ── §2. Product ratings ──────────────────────────────────────────────────────
-- The new card design shows "★ 4.8 (265)" under a product. Those numbers must come from real
-- customer feedback, so the columns are NULL by default and the card renders stars only when a
-- rating has actually been entered in the admin console.
ALTER TABLE public.products
    ADD COLUMN IF NOT EXISTS rating_average NUMERIC(2,1),
    ADD COLUMN IF NOT EXISTS rating_count   INT NOT NULL DEFAULT 0;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM public.products
        WHERE rating_average IS NOT NULL AND (rating_average < 0 OR rating_average > 5)
    ) THEN
        RAISE EXCEPTION '0015: rating_average must be between 0 and 5';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM information_schema.check_constraints
        WHERE constraint_name = 'products_rating_average_range'
    ) THEN
        ALTER TABLE public.products
            ADD CONSTRAINT products_rating_average_range
            CHECK (rating_average IS NULL OR (rating_average >= 0 AND rating_average <= 5));
    END IF;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE '0015 constraint note: %', SQLERRM;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema='public' AND table_name='salon_settings' AND column_name='promo_headline'
    ) THEN
        RAISE EXCEPTION '0015 failed: promo columns were not added';
    END IF;
    RAISE NOTICE '0015 applied: promo band settings + optional product ratings';
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260929000001_reviews.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0016
--   • customer reviews, moderated before they appear
--   • the landing-page carousel stops being hardcoded copy
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. The table ────────────────────────────────────────────────────────────
-- Until now the review carousel rendered six quotes compiled into the component, each
-- hardcoded to five stars. That is business data the platform invented on the salon's
-- behalf, which rule 2 of PROMPTS.md forbids: "Never invent prices, ratings, discounts or
-- business claims … render nothing instead." Reviews now live here, and nothing reaches the
-- public page until a member of staff has approved it.
--
--   service_label  free text ("Bridal package", "Gold facial") — what the visit was for.
--   approved_by    which staff account vetted the row. Not readable from the browser at all
--                  (see the column grants in §2) — it is an audit trail, not display data.
--   source         'website' (submitted through the public form), 'imported' (carried over
--                  from the old hardcoded list, see §3) or 'admin' (entered in the console).
--
-- Deliberately NO contact details, no email, no phone. The public read policy exposes whole
-- rows, and row-level security cannot hide a column — anything in this table is readable by
-- anyone with the publishable key. A reviewer's email therefore belongs in a separate,
-- staff-only table if the salon ever wants one; it must not live here.
CREATE TABLE IF NOT EXISTS public.reviews (
    id              UUID        PRIMARY KEY DEFAULT gen_random_uuid(),
    author_name     VARCHAR(80) NOT NULL,
    service_label   VARCHAR(80),
    rating          SMALLINT    NOT NULL DEFAULT 5,
    body            TEXT        NOT NULL,
    is_approved     BOOLEAN     NOT NULL DEFAULT FALSE,
    approved_at     TIMESTAMPTZ,
    approved_by     UUID        REFERENCES public.profiles(id) ON DELETE SET NULL,
    source          VARCHAR(20) NOT NULL DEFAULT 'website',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT reviews_rating_range CHECK (rating BETWEEN 1 AND 5),
    CONSTRAINT reviews_name_length  CHECK (char_length(btrim(author_name)) BETWEEN 2 AND 80),
    CONSTRAINT reviews_body_length  CHECK (char_length(btrim(body)) BETWEEN 10 AND 1200),

    -- An approved row must record when it was approved; a pending row must not carry a
    -- timestamp. This makes a half-applied moderation state unrepresentable, so the console
    -- cannot accidentally display "approved" rows that were never actually vetted.
    CONSTRAINT reviews_approval_shape CHECK (
        (is_approved = FALSE AND approved_at IS NULL)
        OR (is_approved = TRUE AND approved_at IS NOT NULL)
    )
);

COMMENT ON TABLE public.reviews IS
    'Customer reviews, held for moderation. Publicly readable only when is_approved = true.';

-- One index serves both readers: the public feed is "approved, newest first" and the console
-- queue is "pending, oldest first" — both are scans of this same ordering.
CREATE INDEX IF NOT EXISTS reviews_feed_idx ON public.reviews (is_approved, created_at DESC);

-- ── §2. Authorization (RLS + column grants) ──────────────────────────────────
-- The public may read approved reviews and insert pending ones — nothing else. The insert
-- policy is what makes moderation real rather than cosmetic: a caller cannot hand in an
-- already-approved row, cannot stamp `approved_at`, and cannot label their own row 'admin'.
--
-- RLS is row-level, so on its own it would hand `approved_by` to any browser that asked for
-- it. The column grants below close that: `anon` and `authenticated` may read every column
-- except `approved_by`. Staff keep full row access through the RLS policies, so the console
-- still sees the pending queue.
--
-- ⚠ Consequence for code: PostgREST rejects `select=*` for these roles, because `*` includes
-- `approved_by`. Always name the columns you want (see the PUBLIC_SELECT constant in
-- lib/reviews-api.ts and REVIEW_COLUMNS in lib/reviews-admin-api.ts).
ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY;

REVOKE SELECT ON public.reviews FROM anon, authenticated;
GRANT SELECT (id, author_name, service_label, rating, body, is_approved, approved_at, source, created_at)
    ON public.reviews TO anon, authenticated;

DROP POLICY IF EXISTS "reviews_public_read" ON public.reviews;
CREATE POLICY "reviews_public_read" ON public.reviews
    FOR SELECT TO anon, authenticated
    USING (is_approved = TRUE);

DROP POLICY IF EXISTS "reviews_public_insert" ON public.reviews;
CREATE POLICY "reviews_public_insert" ON public.reviews
    FOR INSERT TO anon, authenticated
    WITH CHECK (
        is_approved = FALSE
        AND approved_at IS NULL
        AND approved_by IS NULL
        AND source = 'website'
        AND rating BETWEEN 1 AND 5
    );

DROP POLICY IF EXISTS "reviews_staff_read" ON public.reviews;
CREATE POLICY "reviews_staff_read" ON public.reviews
    FOR SELECT USING (public.is_staff());

DROP POLICY IF EXISTS "reviews_staff_update" ON public.reviews;
CREATE POLICY "reviews_staff_update" ON public.reviews
    FOR UPDATE USING (public.is_staff())
    WITH CHECK (public.is_staff());

DROP POLICY IF EXISTS "reviews_admin_delete" ON public.reviews;
CREATE POLICY "reviews_admin_delete" ON public.reviews
    FOR DELETE USING (public.is_admin());

-- ── §3. The six quotes that used to be hardcoded ─────────────────────────────
-- Carried over verbatim from components/public/ReviewCarousel.tsx so the owner's copy is not
-- lost, but inserted as PENDING. Nobody has verified the customers behind these names, and the
-- five stars were written into the markup rather than earned, so they must not go straight back
-- onto the live page. Approve the genuine ones in /admin/reviews — that is the only thing
-- standing between them and the site.
--
-- Idempotent: only seeds a table that is still empty, so re-running never duplicates them.
INSERT INTO public.reviews (author_name, service_label, rating, body, is_approved, source)
SELECT v.author_name, v.service_label, v.rating, v.body, FALSE, 'imported'
FROM (VALUES
    ('Sita J.',    'Bridal package',    5::SMALLINT,
     'They did my full bridal look and it lasted the whole night, even through all the dancing. My family still talks about the makeup.'),
    ('Anita P.',   'Keratin smoothing', 5::SMALLINT,
     'My hair was frizzy and unmanageable in the monsoon. After the keratin treatment it is smooth and I barely need to style it.'),
    ('Mina R.',    'Gel nail art',      5::SMALLINT,
     'The nail art is so neat and detailed. It lasted three weeks without chipping, and the price was exactly as shown online.'),
    ('Bimala S.',  'Hair spa',          5::SMALLINT,
     'Very relaxing hair spa. The staff explained what my hair actually needed instead of just selling the most expensive option.'),
    ('Sarita K.',  'Gold facial',       5::SMALLINT,
     'Booked a gold facial before my brother’s wedding. My skin looked fresh and glowing in all the photos.'),
    ('Nirmala D.', 'Beautician course', 5::SMALLINT,
     'I finished the 12-week course and now work at a parlour in Tikapur. Practising on real clients gave me real confidence.')
) AS v(author_name, service_label, rating, body)
WHERE NOT EXISTS (SELECT 1 FROM public.reviews);

-- ── §4. Verify ───────────────────────────────────────────────────────────────
DO $$
DECLARE
    n_policies  INT;
    n_imported  INT;
    can_read_by BOOLEAN;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'reviews'
    ) THEN
        RAISE EXCEPTION '0016 failed: public.reviews was not created';
    END IF;

    IF NOT EXISTS (
        SELECT 1 FROM pg_class c
        JOIN pg_namespace ns ON ns.oid = c.relnamespace
        WHERE ns.nspname = 'public' AND c.relname = 'reviews' AND c.relrowsecurity
    ) THEN
        RAISE EXCEPTION '0016 failed: RLS is not enabled on public.reviews';
    END IF;

    SELECT count(*) INTO n_policies
    FROM pg_policies WHERE schemaname = 'public' AND tablename = 'reviews';

    IF n_policies < 5 THEN
        RAISE EXCEPTION '0016 failed: expected 5 policies on public.reviews, found %', n_policies;
    END IF;

    -- The leak this migration exists to avoid: a browser must not be able to read `approved_by`.
    SELECT has_column_privilege('anon', 'public.reviews', 'approved_by', 'SELECT')
    INTO can_read_by;
    IF can_read_by THEN
        RAISE EXCEPTION '0016 failed: anon can still read reviews.approved_by';
    END IF;

    SELECT count(*) INTO n_imported FROM public.reviews WHERE source = 'imported';

    RAISE NOTICE '0016 applied: public.reviews, % policies, approved_by unreadable by anon, % imported quote(s) awaiting approval',
        n_policies, n_imported;
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260929000002_affiliate_socials.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0017
--   • affiliate applications carry social accounts
--   • an application with no presence is not reviewable, so it cannot be submitted
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. The columns ──────────────────────────────────────────────────────────
-- The programme is approved on the strength of an applicant's audience, but 0008 left nowhere to
-- record it: staff were deciding on a name and a phone number alone, and whatever the applicant
-- said about their reach existed only outside the system.
--
-- Naming and shape mirror `salon_settings` from 0007 — three nullable `*_url` columns holding
-- full `https://` URLs — so the two tables in this schema that describe social accounts describe
-- them the same way.
--
-- Facebook keeps whatever path the applicant supplied, because real profile links look like
-- `facebook.com/share/1Dgw2YFiiZ/` and a two-segment path must survive intact. Instagram and
-- TikTok are canonicalised to `<host>/<handle>`.
ALTER TABLE public.affiliates
    ADD COLUMN IF NOT EXISTS facebook_url  VARCHAR(200),
    ADD COLUMN IF NOT EXISTS instagram_url VARCHAR(200),
    ADD COLUMN IF NOT EXISTS tiktok_url    VARCHAR(200);

COMMENT ON COLUMN public.affiliates.facebook_url IS
    'Applicant Facebook profile URL, as supplied (kept verbatim — share links have two path segments).';
COMMENT ON COLUMN public.affiliates.instagram_url IS
    'Canonical Instagram profile URL, https://www.instagram.com/<handle>.';
COMMENT ON COLUMN public.affiliates.tiktok_url IS
    'Canonical TikTok profile URL, https://www.tiktok.com/@<handle>.';

-- Shape constraints. A blank string is treated as absent rather than rejected, so a form that
-- posts `""` for an untouched field cannot fail the insert with a confusing constraint error.
-- These mirror the client-side rules in `lib/socials.ts`; that module is the friendly explanation,
-- this is the guarantee.
ALTER TABLE public.affiliates DROP CONSTRAINT IF EXISTS affiliates_facebook_url_shape;
ALTER TABLE public.affiliates ADD CONSTRAINT affiliates_facebook_url_shape CHECK (
    NULLIF(btrim(facebook_url), '') IS NULL
    OR (
        btrim(facebook_url) ~* '^https://(www\.|m\.|web\.)?(facebook\.com|fb\.com|fb\.me)/\S+$'
        AND char_length(btrim(facebook_url)) <= 200
    )
);

ALTER TABLE public.affiliates DROP CONSTRAINT IF EXISTS affiliates_instagram_url_shape;
ALTER TABLE public.affiliates ADD CONSTRAINT affiliates_instagram_url_shape CHECK (
    NULLIF(btrim(instagram_url), '') IS NULL
    OR (
        btrim(instagram_url) ~* '^https://(www\.)?instagram\.com/\S+$'
        AND char_length(btrim(instagram_url)) <= 200
    )
);

ALTER TABLE public.affiliates DROP CONSTRAINT IF EXISTS affiliates_tiktok_url_shape;
ALTER TABLE public.affiliates ADD CONSTRAINT affiliates_tiktok_url_shape CHECK (
    NULLIF(btrim(tiktok_url), '') IS NULL
    OR (
        btrim(tiktok_url) ~* '^https://(www\.)?tiktok\.com/@?\S+$'
        AND char_length(btrim(tiktok_url)) <= 200
    )
);

-- ── §2. An application must show at least one account ────────────────────────
-- Enforced in the INSERT policy rather than a CHECK constraint, and this distinction is the whole
-- point: the requirement applies to *applicants*, not to rows. Staff editing an approved member in
-- the console — clearing a dead TikTok link, say — must not be blocked by a rule about applying.
--
-- Rewritten from 0008; the earlier terms (pending, zero earnings) are unchanged.
DROP POLICY IF EXISTS affiliates_apply_public ON public.affiliates;
CREATE POLICY affiliates_apply_public ON public.affiliates
    FOR INSERT WITH CHECK (
        status = 'pending'
        AND total_earned_npr = 0
        AND total_paid_npr = 0
        AND COALESCE(
              NULLIF(btrim(facebook_url), ''),
              NULLIF(btrim(instagram_url), ''),
              NULLIF(btrim(tiktok_url), '')
            ) IS NOT NULL
    );

-- ── §3. Verify ───────────────────────────────────────────────────────────────
DO $$
DECLARE
    n_cols INT;
    policy_requires_social BOOLEAN;
BEGIN
    SELECT count(*) INTO n_cols
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'affiliates'
      AND column_name IN ('facebook_url', 'instagram_url', 'tiktok_url');

    IF n_cols <> 3 THEN
        RAISE EXCEPTION '0017 failed: expected 3 social columns on affiliates, found %', n_cols;
    END IF;

    -- The policy's WITH CHECK must actually mention the social requirement; a policy that lost it
    -- in an edit would otherwise pass every other check here.
    SELECT COALESCE(with_check, '') ILIKE '%facebook_url%' INTO policy_requires_social
    FROM pg_policies
    WHERE schemaname = 'public' AND tablename = 'affiliates' AND policyname = 'affiliates_apply_public';

    IF NOT policy_requires_social THEN
        RAISE EXCEPTION '0017 failed: affiliates_apply_public does not require a social account';
    END IF;

    RAISE NOTICE '0017 applied: 3 social columns on affiliates; public applications require at least one';
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260930000001_watermark_settings.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- Product watermark / logo settings.
--
-- Three columns on the single-row `salon_settings` table, following the pattern of migrations
-- 0008 / 0011 / 0013 / 0015 rather than introducing a key/value settings table:
--
--   watermark_enabled   Master switch for the brand badge drawn over product imagery.
--   watermark_logo_url  Public URL of the uploaded PNG. NULL means "nothing uploaded", which the
--                       storefront renders as no badge at all — never an empty box or a broken
--                       image tag.
--   watermark_size_px   Badge height in CSS pixels, bounded to the range the admin slider offers.
--
-- Only the URL is stored, not the binary: the PNG goes to the existing public `gallery` bucket
-- (which already allows image/png at 8 MB) and the settings row keeps a short string, so the asset
-- is CDN-served and the row stays cheap to read on every page render.

ALTER TABLE public.salon_settings
  ADD COLUMN IF NOT EXISTS watermark_enabled  BOOLEAN NOT NULL DEFAULT TRUE,
  ADD COLUMN IF NOT EXISTS watermark_logo_url TEXT,
  ADD COLUMN IF NOT EXISTS watermark_size_px  INTEGER NOT NULL DEFAULT 44;

-- Bounded in the database as well as in the slider, so a direct API call cannot store a value the
-- interface has no way to represent or clear.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'salon_settings_watermark_size_px_check'
  ) THEN
    ALTER TABLE public.salon_settings
      ADD CONSTRAINT salon_settings_watermark_size_px_check
      CHECK (watermark_size_px BETWEEN 32 AND 64);
  END IF;
END $$;

COMMENT ON COLUMN public.salon_settings.watermark_logo_url IS
  'Public URL of the PNG brand mark overlaid on product imagery. NULL = not set.';
COMMENT ON COLUMN public.salon_settings.watermark_size_px IS
  'Height of the product-image badge in CSS pixels (32-64).';

-- Existing staff-update policies on `salon_settings` already cover these columns, so no new RLS
-- rule is needed: whoever may edit the salon's phone number may edit its watermark.

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260930000002_payment_accounts.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0020
--   • the shop can take money into more than one account
--   • each account carries its own QR, name and number
--   • the single QR from 0011 is carried over, not dropped
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. Why a table and not more columns ─────────────────────────────────────
-- 0011 put exactly one QR on the shop: `salon_settings.payment_qr_image_url` plus a
-- `payment_qr_content` string to encode. That is one destination. A shop that banks with Nabil and
-- also accepts Khalti and eSewa has three, each with its own QR exported from its own app, and the
-- owner needs to add or retire one without a developer.
--
-- Three more `payment_qr_*_2` columns would have been the other way to do it, and it is the wrong
-- one: the number of accounts is genuinely open-ended, and every consumer of the settings row would
-- have had to learn about `_2`, `_3`, `_4`. A child table keeps `salon_settings` a settings row.
--
-- The old columns stay in place and stay populated. Nothing here drops them: `PaymentQR` still
-- reads them as the fallback for a shop that has not created any account rows yet, and a rollback
-- that happened to precede this migration must still find the owner's QR where it left it.
CREATE TABLE IF NOT EXISTS public.payment_accounts (
    id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),

    -- What the customer sees as the option, e.g. "Nabil Bank" or "Khalti".
    label          VARCHAR(80) NOT NULL,

    -- How it is grouped at checkout. Deliberately a small closed set: this drives which icon and
    -- which label the customer sees, and a free-text field here would produce a different set of
    -- groupings every time the owner typed a new one.
    kind           VARCHAR(20) NOT NULL DEFAULT 'bank',

    -- Account holder or merchant name, as it should appear on a receipt.
    account_name   VARCHAR(120),

    -- Account, mobile or merchant number. Shown in full: this is the whole point of the row, and
    -- the customer has to be able to check they are paying the right account.
    account_number VARCHAR(60),

    -- The QR the customer scans. Exported from the provider's own app and uploaded in admin, which
    -- is why it is a stored image rather than something generated here — the provider decides what
    -- its own QR encodes.
    qr_image_url   TEXT,

    -- Anything the owner wants printed under this option, e.g. "Send a screenshot to confirm".
    instructions   TEXT,

    display_order  INT NOT NULL DEFAULT 0,
    is_active      BOOLEAN NOT NULL DEFAULT TRUE,
    created_at     TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),
    updated_at     TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    -- A blank label is treated as absent rather than rejected, so a form posting `""` for an
    -- untouched field cannot fail the insert with a confusing constraint error.
    CONSTRAINT payment_accounts_label_present CHECK (char_length(btrim(label)) > 0),
    CONSTRAINT payment_accounts_kind_known CHECK (kind IN ('bank', 'wallet', 'other'))
);

COMMENT ON TABLE  public.payment_accounts IS
    'One row per payment destination the shop accepts (bank, wallet or other), each with its own QR.';
COMMENT ON COLUMN public.payment_accounts.kind IS
    'Grouping shown at checkout: bank, wallet or other.';
COMMENT ON COLUMN public.payment_accounts.qr_image_url IS
    'Public URL of the QR image exported from the provider app. NULL renders no QR for this account.';

-- Checkout asks for the active set in display order on every render, so the index matches the
-- query rather than the primary key.
CREATE INDEX IF NOT EXISTS payment_accounts_active_order_idx
    ON public.payment_accounts (is_active, display_order);

DROP TRIGGER IF EXISTS payment_accounts_touch_updated_at ON public.payment_accounts;
CREATE TRIGGER payment_accounts_touch_updated_at
    BEFORE UPDATE ON public.payment_accounts
    FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();

-- ── §2. Access ───────────────────────────────────────────────────────────────
-- The checkout page is public — a visitor must be able to see where to send money before they have
-- an account — so the active rows are world-readable. Everything a customer needs to pay is here by
-- design: this table holds no secret, only the shop's own published account numbers.
ALTER TABLE public.payment_accounts ENABLE ROW LEVEL SECURITY;

REVOKE SELECT ON public.payment_accounts FROM anon, authenticated;
GRANT SELECT (id, label, kind, account_name, account_number, qr_image_url, instructions,
              display_order, is_active, created_at)
    ON public.payment_accounts TO anon, authenticated;

DROP POLICY IF EXISTS "payment_accounts_public_read" ON public.payment_accounts;
CREATE POLICY "payment_accounts_public_read" ON public.payment_accounts
    FOR SELECT TO anon, authenticated
    USING (is_active = TRUE);

-- Staff see the retired ones too, so a disabled account can be edited back on rather than being
-- invisible and therefore unreachable.
DROP POLICY IF EXISTS "payment_accounts_staff_read" ON public.payment_accounts;
CREATE POLICY "payment_accounts_staff_read" ON public.payment_accounts
    FOR SELECT USING (public.is_staff());

DROP POLICY IF EXISTS "payment_accounts_staff_insert" ON public.payment_accounts;
CREATE POLICY "payment_accounts_staff_insert" ON public.payment_accounts
    FOR INSERT WITH CHECK (public.is_staff());

DROP POLICY IF EXISTS "payment_accounts_staff_update" ON public.payment_accounts;
CREATE POLICY "payment_accounts_staff_update" ON public.payment_accounts
    FOR UPDATE USING (public.is_staff())
    WITH CHECK (public.is_staff());

DROP POLICY IF EXISTS "payment_accounts_admin_delete" ON public.payment_accounts;
CREATE POLICY "payment_accounts_admin_delete" ON public.payment_accounts
    FOR DELETE USING (public.is_admin());

-- ── §3. Carry the existing QR across ─────────────────────────────────────────
-- The shop already has one working destination configured in `salon_settings`. Without this the
-- owner would sign in to find an empty list and conclude their QR had been deleted, so a single row
-- is seeded from it — but only when there is something to seed, and only when the table is empty,
-- so re-running the migration can never duplicate it.
INSERT INTO public.payment_accounts (label, kind, account_name, account_number, qr_image_url, instructions, display_order)
SELECT
    'eSewa',
    'wallet',
    'Alikati Beauty Home',
    -- `esewa:9869512756?amount={amount}` → `9869512756`. NULL when the content is not in that form.
    NULLIF(split_part(split_part(s.settings_content, ':', 2), '?', 1), ''),
    s.settings_image,
    'Scan the QR to pay, then upload your payment screenshot at checkout.',
    0
FROM (
    SELECT
        NULLIF(btrim(COALESCE(payment_qr_content, '')), '')     AS settings_content,
        NULLIF(btrim(COALESCE(payment_qr_image_url, '')), '')   AS settings_image
    FROM public.salon_settings
    WHERE id = 1
) AS s
WHERE (s.settings_content IS NOT NULL OR s.settings_image IS NOT NULL)
  AND NOT EXISTS (SELECT 1 FROM public.payment_accounts);

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260930000003_payment_accounts_read_grant.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0021
--   • anon can actually read the payment accounts
--   • a table-level SELECT, not the column list 0020 used
-- ═════════════════════════════════════════════════════════════════════════════

-- ── What went wrong in 0020 ──────────────────────────────────────────────────
-- 0020 revoked SELECT and re-granted it column by column, copying the pattern from `reviews`:
--
--     REVOKE SELECT ON public.payment_accounts FROM anon, authenticated;
--     GRANT  SELECT (id, label, kind, …) ON public.payment_accounts TO anon, authenticated;
--
-- That pattern is right for `reviews`, which hides internal columns (`approved_by`, `source`) from
-- anonymous readers while still letting them select the published ones — and `reviews` works
-- because every query against it names its columns explicitly (`REVIEW_COLUMNS`).
--
-- It is wrong here. `payment_accounts` has nothing to withhold: every column is either the label
-- the customer picks, the account to pay into, or ordering metadata the customer-facing query sorts
-- by. The application reads it with `select('*')`, and `select('*')` needs SELECT on the **table**,
-- not on a list of columns — so the checkout's own query was refused with `42501 permission denied`
-- and the payment step would have shown a customer nothing at all. `has_any_column_privilege` was
-- true the whole time, which is what made this quiet: the grant looked present in the schema dump.
--
-- Verified before and after with an anonymous key, because that is the role that actually renders
-- the checkout.
REVOKE SELECT ON public.payment_accounts FROM anon, authenticated;
GRANT  SELECT ON public.payment_accounts TO anon, authenticated;

COMMENT ON TABLE public.payment_accounts IS
    'One row per payment destination the shop accepts (bank, wallet or other), each with its own QR. '
    'Readable in full by anonymous visitors: the shop publishes these details so customers can pay. '
    'Visibility is controlled by `is_active`, enforced in the RLS policy, not by column privileges.';

-- The column-level grants 0020 left behind are now redundant alongside the table-level one. Removed
-- so the schema says one thing rather than two.
DO $$
DECLARE
    col TEXT;
BEGIN
    FOREACH col IN ARRAY ARRAY[
        'id', 'label', 'kind', 'account_name', 'account_number',
        'qr_image_url', 'instructions', 'display_order', 'is_active', 'created_at'
    ] LOOP
        EXECUTE format('REVOKE SELECT (%I) ON public.payment_accounts FROM anon, authenticated', col);
    END LOOP;
END $$;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260930000004_payment_provider_schema.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0022
--   • a payment account is identified by its provider, not a free-form label
--   • bank destinations carry a bank name and branch
--   • the checkout can group accounts into eSewa / Khalti / Bank Transfer tabs
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. `kind` becomes `provider`, with the provider's own names ─────────────
-- 0020 modelled the grouping as bank / wallet / other. That is the wrong axis: the customer picks
-- *eSewa* or *Khalti* or their bank, and "wallet" is a category an owner would have to translate in
-- their head twice — once when adding the account and again when reading the checkout. Renaming to
-- the providers the shop actually uses lets the checkout render a tab per provider without a
-- mapping table, and lets the admin form offer the real choices.
ALTER TABLE public.payment_accounts DROP CONSTRAINT IF EXISTS payment_accounts_kind_known;
ALTER TABLE public.payment_accounts RENAME COLUMN kind TO provider;

-- Map the old vocabulary onto the new one before the constraint is reapplied, so the migration fails
-- loudly here if a value does not fit rather than silently leaving an unconstrained column.
UPDATE public.payment_accounts
SET provider = CASE
    WHEN label ILIKE '%esewa%'  THEN 'esewa'
    WHEN label ILIKE '%khalti%' THEN 'khalti'
    WHEN label ILIKE '%bank%'   THEN 'bank'
    ELSE 'other'
END
WHERE provider = 'wallet';

UPDATE public.payment_accounts SET provider = 'other' WHERE provider NOT IN ('esewa', 'khalti', 'bank', 'other');

ALTER TABLE public.payment_accounts
    ADD CONSTRAINT payment_accounts_provider_known
    CHECK (provider IN ('esewa', 'khalti', 'bank', 'other'));

COMMENT ON COLUMN public.payment_accounts.provider IS
    'Which service the money goes to: esewa, khalti, bank or other. Drives the checkout tab.';

-- ── §2. Bank details, and a clearer name for the number ─────────────────────
-- "Account number" was wrong for a wallet, where the same field holds a mobile number.
ALTER TABLE public.payment_accounts RENAME COLUMN account_number TO account_identifier;

ALTER TABLE public.payment_accounts
    ADD COLUMN IF NOT EXISTS bank_name   TEXT,
    ADD COLUMN IF NOT EXISTS bank_branch TEXT;

COMMENT ON COLUMN public.payment_accounts.account_identifier IS
    'Wallet/mobile number, or the bank account number.';
COMMENT ON COLUMN public.payment_accounts.bank_name IS
    'Bank only. NULL for wallets.';

-- The free-form `label` existed to name an account before the provider did that job ("Nmb"). That
-- information belongs in `bank_name`, so it is moved there rather than dropped — these rows are
-- real configurations, and losing the bank's name would leave the owner with an unnamed account.
UPDATE public.payment_accounts
SET bank_name = COALESCE(bank_name, NULLIF(btrim(label), ''))
WHERE provider = 'bank' AND bank_name IS NULL;

-- New accounts are named by their provider, so `label` is no longer required and the old
-- "must not be blank" rule would reject an insert that legitimately omits it.
ALTER TABLE public.payment_accounts ALTER COLUMN label DROP NOT NULL;
ALTER TABLE public.payment_accounts DROP CONSTRAINT IF EXISTS payment_accounts_label_present;

COMMENT ON COLUMN public.payment_accounts.label IS
    'Optional display override. When NULL the checkout names the account after its provider.';

-- ── §3. Keep the read path working ───────────────────────────────────────────
-- Renaming a column drops nothing here: 0021 granted SELECT on the whole table, so the new columns
-- are readable without another grant. Recorded explicitly because the opposite assumption (a
-- column list) is exactly what broke the checkout in 0020.
GRANT SELECT ON public.payment_accounts TO anon, authenticated;

-- ─────────────────────────────────────────────────────────────────────────────
-- 20260930000005_media_library.sql
-- ─────────────────────────────────────────────────────────────────────────────

-- ═════════════════════════════════════════════════════════════════════════════
-- Alikati Beauty Home — 0023
--   • a media library with its own categories, so editorial assets have a home
--   • payment QRs stay out of it: they are configuration, not content
-- ═════════════════════════════════════════════════════════════════════════════

-- ── §1. Why a library at all ─────────────────────────────────────────────────
-- Until now every uploaded asset lived as a bare URL in whichever column happened to need it: a
-- product's `images`, a category's `image_url`, a hero's settings row, the watermark, a payment QR.
-- Nothing listed them, so a file could only be found by remembering where it was used, and nothing
-- could be reused. This is the catalogue of what has been uploaded.
--
-- Files themselves stay in the public `gallery` bucket under `{category_slug}/{filename}` — the
-- bucket is already the project's public asset store and needs no new policies. The tables here
-- record what is in it; they do not hold the bytes.
CREATE TABLE IF NOT EXISTS public.media_categories (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug          VARCHAR(60) NOT NULL UNIQUE,
    name          VARCHAR(80) NOT NULL,
    -- Seeded categories cannot be deleted: the library's filters would empty out and any asset
    -- filed under one would be orphaned with no way to find it again.
    is_system     BOOLEAN NOT NULL DEFAULT FALSE,
    display_order INT NOT NULL DEFAULT 0,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT media_categories_slug_shape CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);

CREATE TABLE IF NOT EXISTS public.media_assets (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- SET NULL rather than CASCADE: deleting a category must not silently delete the images filed
    -- under it. The asset survives as uncategorised and can be refiled.
    category_id  UUID REFERENCES public.media_categories(id) ON DELETE SET NULL,
    -- Path inside the bucket, kept so the object can be removed and so `{category_slug}/…` can be
    -- verified. `url` is the public URL the site embeds.
    path         TEXT NOT NULL,
    url          TEXT NOT NULL,
    filename     TEXT NOT NULL,
    mime_type    VARCHAR(80),
    size_bytes   BIGINT,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT timezone('utc'::text, now()),

    CONSTRAINT media_assets_path_unique UNIQUE (path)
);

CREATE INDEX IF NOT EXISTS media_assets_category_created_idx
    ON public.media_assets (category_id, created_at DESC);

COMMENT ON TABLE  public.media_categories IS
    'Folders for the admin media library. The four defaults are seeded with is_system = true.';
COMMENT ON TABLE  public.media_assets IS
    'Catalogue of files uploaded to the public gallery bucket. The bytes live in Storage, not here.';
COMMENT ON COLUMN public.media_assets.path IS
    'Object path inside the gallery bucket, e.g. product-images/1727-abc.png.';

-- The four defaults the brief names. `ON CONFLICT DO NOTHING` so re-running the migration cannot
-- duplicate them, and so an owner who has renamed one keeps their name.
INSERT INTO public.media_categories (slug, name, is_system, display_order) VALUES
    ('product-images',    'Product Images',     TRUE, 0),
    ('hero-banners',      'Hero & Banners',     TRUE, 1),
    ('watermarks-logos',  'Watermarks & Logos', TRUE, 2),
    ('general-gallery',   'General Gallery',    TRUE, 3)
ON CONFLICT (slug) DO NOTHING;

-- ── §2. Access ───────────────────────────────────────────────────────────────
-- Staff only, and unlike the payment accounts there is no public read. The storefront embeds asset
-- URLs directly and never queries these tables, so nothing on the public site needs them — and the
-- narrower the surface, the less there is to get wrong. Note this is a **table-level** grant: the
-- lesson from 0020 is that column grants break any `select('*')`, which is what this library uses.
ALTER TABLE public.media_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.media_assets     ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON public.media_categories FROM anon, authenticated;
REVOKE ALL ON public.media_assets     FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.media_categories TO authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.media_assets     TO authenticated;

DROP POLICY IF EXISTS "media_categories_staff_all" ON public.media_categories;
CREATE POLICY "media_categories_staff_all" ON public.media_categories
    FOR ALL TO authenticated
    USING (public.is_staff()) WITH CHECK (public.is_staff());

DROP POLICY IF EXISTS "media_assets_staff_all" ON public.media_assets;
CREATE POLICY "media_assets_staff_all" ON public.media_assets
    FOR ALL TO authenticated
    USING (public.is_staff()) WITH CHECK (public.is_staff());

-- A seeded category is protected from deletion in the database, not only in the interface, so an
-- API call cannot remove the library's own filters.
CREATE OR REPLACE FUNCTION public.protect_system_media_categories()
RETURNS TRIGGER
LANGUAGE plpgsql
AS $$
BEGIN
    IF OLD.is_system THEN
        RAISE EXCEPTION 'The "%" category is built in and cannot be deleted.', OLD.name;
    END IF;
    RETURN OLD;
END $$;

DROP TRIGGER IF EXISTS media_categories_protect_system ON public.media_categories;
CREATE TRIGGER media_categories_protect_system
    BEFORE DELETE ON public.media_categories
    FOR EACH ROW EXECUTE FUNCTION public.protect_system_media_categories();

COMMIT;

-- ═════════════════════════════════════════════════════════════════════════════
-- Done. Expected: 14 tables in the public schema, RLS enabled on all of them, and one row
-- in salon_settings. Verify with:
--   select count(*) from information_schema.tables where table_schema = 'public';
--   select count(*) from public.salon_settings;   -- must be 1
-- ═════════════════════════════════════════════════════════════════════════════
